function sc = scenario_era5_real()
%SCENARIO_ERA5_REAL
% Scenario definition for real ERA5-driven relative humidity.
%
% TARGET BEHAVIOR:
%   - CALIPSO AP MAT is required.
%   - ERA5 hourly MAT is required.
%   - Required ERA5 variables/time coverage must pass validation.
%   - RH is generated by CALIPSO-ERA5 time/space/height matching.
%
% IMPORTANT:
%   Missing ERA5 must never silently fall back to RH = 50%.

sc.name = 'era5_real';
sc.version = 'v1';

sc.rh_mode = 'era5_real';
sc.rh_source = 'ERA5';
sc.rh_value = NaN;
sc.rh_unit = 'percent';

% Input requirements
sc.require_calipso_ap = true;
sc.require_era5 = true;

% ERA5 behavior
sc.allow_era5_access = true;
sc.require_complete_era5_day = true;

% Required ERA5 variables for the current interface
sc.required_era5_variables = {'r', 'z'};
sc.surface_pressure_used = false;
sc.below_ground_mask = 'none';
sc.vertical_profile_gate = 'finite_and_strictly_monotonic_height';
sc.vertical_extrapolation = 'none';

% Missing-RH policy
sc.allow_downstream_rh_fallback = false;
sc.error_if_rh_missing = true;

% Incomplete-day policy
sc.incomplete_day_action = 'skip_and_record';

% Product identity
sc.product_tag = 'era5-real';

% Scientific status
sc.scientific_role = 'formal_era5_driven_scenario';

end
